sys_script_include.script:
var instanceUtils = Class.create();
instanceUtils.prototype = {
    initialize: function() {
    },

	createInstance: function(template, record, status, attachmentSysId, msg, outputType) {
        var inst = new GlideRecord('x_2162040_documate_instance');
        inst.initialize();

        inst.setValue('template', template.getUniqueValue());
        inst.setValue('table', record.getTableName());
        inst.setValue('record_sys_id', record.getUniqueValue());
        inst.setValue('status', status);
        inst.setValue('attachment_sys_id', attachmentSysId || '');
        inst.setValue('message', msg || '');

        return inst.insert();
    },

    /*
     * Copy generated document attachment from source record to DocuMate instance record.
     */
    copyAttachmentToInstance: function(attachmentSysId, instance) {
        try {
            // accept either the instance sys_id or an instance GlideRecord
            if (typeof instance == 'string') {
                var instGr = new GlideRecord('x_2162040_documate_instance');
                instance = instGr.get(instance) ? instGr : null;
            }

            if (!attachmentSysId || !instance || !instance.isValidRecord()) {
                return false;
            }

            var att = new GlideRecord('sys_attachment');
            if (!att.get(attachmentSysId)) {
                return false;
            }

            var sa = new GlideSysAttachment();
            var content = sa.getContent(att);

            if (content === null || content === undefined) {
                gs.error('DocuMate: Attachment content empty. attachmentSysId=' + attachmentSysId);
                return false;
            }

            var newAttachmentId = sa.write(
                instance,
                att.getValue('file_name'),
                att.getValue('content_type'),
                content
            );

            return !!newAttachmentId;

        } catch (ex) {
            gs.error('DocuMate: Failed to copy attachment to instance. Error: ' + ex.toString());
            return false;
        }
    },

    createSuccess: function(template, record, attachmentSysId, warnings) {
        var msg = 'SuccessFully Created';

        if (warnings && warnings.length) {
            msg = 'Created with ' + warnings.length + ' warning(s) - please check the configuration:\n- ' +
                warnings.join('\n- ');
        }

        return this.createInstance(template, record, 'success', attachmentSysId, msg, 'doc');
    },

    createFailure: function(template, record, msg) {
        return this.createInstance(template, record, 'failed', '', msg, 'doc');
    },

    createSkipped: function(template, record, msg) {
        return this.createInstance(template, record, 'skipped', '', msg, 'doc');
    },

    type: 'instanceUtils'
};
